import sys

def main():
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) < 2:
        return
    txt = lines[0]
    pat = lines[1]

    n = len(txt)
    m = len(pat)

    if m > n:
        print("-1")
        return

    pi = [0] * m
    k = 0
    for q in range(1, m):
        while k > 0 and pat[k] != pat[q]:
            k = pi[k - 1]
        if pat[k] == pat[q]:
            k += 1
        pi[q] = k

    result = []
    q = 0
    for i in range(n):
        while q > 0 and pat[q] != txt[i]:
            q = pi[q - 1]
        if pat[q] == txt[i]:
            q += 1
        if q == m:
            result.append(i - m + 2)
            q = pi[q - 1]

    if not result:
        print("-1")
    else:
        print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
